SELECT * FROM settlement_batch


        AND batch_type = #{batchType}


        AND batch_status = #{batchStatus}


        AND DATE(create_time) >= #{startDate}


        AND DATE(create_time) <= #{endDate}


        AND org_id = #{orgId}


ORDER BY create_time DESC

SELECT * FROM settlement_batch
WHERE batch_status = #{batchStatus} AND org_id = #{orgId}
ORDER BY create_time DESC

SELECT * FROM settlement_batch
WHERE batch_status = 'FAILED'
AND retry_count < max_retry_count
AND next_retry_time <= #{currentTime}
AND org_id = #{orgId}
ORDER BY next_retry_time ASC

SELECT COUNT(*) as totalCount, SUM(CASE WHEN batch_status = 'CREATED' THEN 1 ELSE 0 END) as createdCount, SUM(CASE WHEN batch_status = 'SCHEDULED' THEN 1 ELSE 0 END) as scheduledCount, SUM(CASE WHEN batch_status = 'RUNNING' THEN 1 ELSE 0 END) as runningCount, SUM(CASE WHEN batch_status = 'COMPLETED' THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN batch_status = 'FAILED' THEN 1 ELSE 0 END) as failedCount, SUM(CASE WHEN batch_status = 'CANCELLED' THEN 1 ELSE 0 END) as cancelledCount, SUM(transaction_count) as totalTransactionCount, SUM(success_count) as totalSuccessCount, SUM(failed_count) as totalFailedCount, SUM(total_amount) as totalAmount, AVG(execution_duration) as avgExecutionDuration FROM settlement_batch WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}

SELECT batch_type, COUNT(*) as count, SUM(CASE WHEN batch_status = 'COMPLETED' THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN batch_status = 'FAILED' THEN 1 ELSE 0 END) as failedCount, SUM(transaction_count) as totalTransactionCount, SUM(total_amount) as totalAmount, AVG(execution_duration) as avgExecutionDuration FROM settlement_batch WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY batch_type ORDER BY count DESC

SELECT batch_status, COUNT(*) as count, SUM(transaction_count) as totalTransactionCount, SUM(total_amount) as totalAmount, AVG(execution_duration) as avgExecutionDuration FROM settlement_batch WHERE org_id = #{orgId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY batch_status ORDER BY count DESC

SELECT batch_type, AVG(execution_duration) as avgDuration, AVG(transaction_count / NULLIF(execution_duration, 0) * 60) as avgThroughput, AVG(success_count * 100.0 / NULLIF(transaction_count, 0)) as avgSuccessRate, COUNT(*) as batchCount FROM settlement_batch WHERE org_id = #{orgId} AND batch_status = 'COMPLETED' AND execution_duration > 0
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY batch_type ORDER BY avgThroughput DESC

SELECT HOUR(scheduled_time) as scheduleHour, COUNT(*) as batchCount, AVG(execution_duration) as avgDuration, SUM(transaction_count) as totalTransactionCount, AVG(success_count * 100.0 / NULLIF(transaction_count, 0)) as avgSuccessRate FROM settlement_batch WHERE org_id = #{orgId} AND batch_status = 'COMPLETED' AND scheduled_time IS NOT NULL
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY HOUR(scheduled_time) ORDER BY scheduleHour

SELECT error_message, COUNT(*) as count, batch_type, AVG(retry_count) as avgRetryCount, MAX(create_time) as lastFailureTime FROM settlement_batch WHERE org_id = #{orgId} AND batch_status = 'FAILED' AND error_message IS NOT NULL
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY error_message, batch_type ORDER BY count DESC
